create or replace function public.sales_commercial_quote_v610(p_tenant_id uuid,p_location_id uuid,p_device_id uuid,p_order_type text,p_items jsonb,p_discount_type text default 'none',p_discount_value numeric default 0,p_charge_selections jsonb default '[]'::jsonb) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;perform private.erp_validate_transaction_origin(p_tenant_id,p_location_id,p_device_id,'sales');return private.sales_commercial_expand_v610(p_tenant_id,p_order_type,p_items,p_discount_type,p_discount_value,p_charge_selections);end;$$;;
